@CheckResult @NonNull
    public static Single<Palette> generate(@NonNull final Bitmap bitmap) {
        return Single.fromCallable(new Callable<Palette>() {
            @Override
            public Palette call() throws Exception {
                return Palette.from(bitmap).generate();
            }
        });
    }
